package theme

import (
	"strings"
	"testing"

	"github.com/charmbracelet/lipgloss"
	"github.com/mattn/go-runewidth"

	"github.com/anthnel/devdesk/internal/config"
)

// Gauge is now just width copies of one glyph — the value lives entirely in
// GaugeFillWidth's cut point and in which colour a caller puts on either side
// of it (§3.71, third revision). These tests are split the same way: what the
// text looks like, what the cut point says, and what colour each side takes.

// A gauge is measured by datatable before it is coloured, so its rendered
// width has to be exactly what the column declared, under an East Asian
// locale as much as under this one.
func TestAGaugeIsExactlyAsWideAsItAsksFor(t *testing.T) {
	eastAsian := &runewidth.Condition{EastAsianWidth: true}

	for _, width := range []int{1, 2, 6, 10, 20} {
		bar := Gauge(50, width)
		if got := runewidth.StringWidth(bar); got != width {
			t.Fatalf("Gauge(%d) measures %d cells, want %d: %q", width, got, width, bar)
		}
		if got := eastAsian.StringWidth(bar); got != width {
			t.Fatalf("Gauge(%d) measures %d cells under an East Asian locale, want %d: %q",
				width, got, width, bar)
		}
	}
}

// Gauge does not depend on a value at all: every cell is the same glyph,
// whatever the caller will go on to colour.
func TestGaugeIsUniform(t *testing.T) {
	if got, want := Gauge(50, 6), "░░░░░░"; got != want {
		t.Errorf("Gauge(6) = %q, want %q", got, want)
	}
}

// A width of zero or less renders nothing rather than a negative repeat count.
func TestGaugeSurvivesAnEmptyWidth(t *testing.T) {
	for _, width := range []int{0, -1} {
		if got := Gauge(50, width); got != "" {
			t.Errorf("Gauge(%d) = %q, want the empty string", width, got)
		}
	}
}

func TestGaugeFillWidthIsProportional(t *testing.T) {
	tests := []struct {
		name string
		pct  float64
		want int
	}{
		// An idle container fills zero cells, not a token one: a tenth of a
		// ten-cell bar *is* 10%, so lighting one for 0.1% would overstate it
	switch state {
	case "error":
		s.Selected = s.Selected.
			Background(ColorError).
			Foreground(ColorBlack)
	case "busy":
		// A row an action is running on. It outranks "error" rather than the
		// other way round: `exited` is precisely what is about to stop being
		// true, so the transition is the newer fact.
		//
		// ColorHighlight is not an arbitrary pick — the containers view already
		// paints docker's own transitional states (`created`, `restarting`) with
		// it, and a transition DevDesk started is the same kind of thing.
		s.Selected = s.Selected.
			Background(ColorHighlight).
			Foreground(ColorBlack)
// Point 3 makes the declaration a preference and not a guarantee, deliberately:
// fewer columns that are right beats every column wrong. The alternative —
// truncating the exact-width columns as a last resort — renders 142 as "14…",
// and nothing on screen distinguishes a truncated number from a small one.

// borderWidth is the viewport's two vertical borders.
const borderWidth = 2

// cellPadding is what bubbles/table adds per column — Padding(0, 1).
const cellPadding = 2

// IconColumnWidth is the width of a first column that carries a glyph and
// nothing else: the glyph, plus one cell so it never touches the text beside
// it. Two, not one — a Nerd Font glyph renders at double width on some
// terminals and single on others, and one cell would clip it wherever it
// renders wide.
//
// It is exported because it is the same column in three tables, and a magic 2
// repeated in three packages is a number three places are free to disagree
// about. TestAnIconColumnIsUntitledAndTwoCellsWide reads the sources for the
// ones that do.
const IconColumnWidth = 2

// availableFor returns the width the columns have to share, given the full
// viewport width and the number of columns that will actually be rendered.
// Negative when the terminal cannot even hold the borders and the padding,
// which the solver reads as "no room at all".

